  public static ImportResult Import(string file,string mediaFolder){string ext=Path.GetExtension(file).ToLowerInvariant();if(ext==".mid"||ext==".midi")return MidiFileImport.Load(file);if(ext==".dawproject")return ImportDawProject(file,mediaFolder);if(ext==".als")return ImportAls(file);if(ext==".flp")return ImportFlp(file);throw new InvalidDataException("Unsupported import format.");}
  public static ImportResult ImportDawProject(string file,string mediaFolder){
