     var t=ProjectFactory.CreateTrack((string)node.Attribute("name")??"Imported",((string)node.Attribute("contentType")??"").Contains("notes")?TrackType.Midi:TrackType.Audio);t.ExternalMidi=false;
     if(channel!=null){t.GainDb=Math.Max(-96,Math.Min(12,20*Math.Log10(Math.Max(0.000016,D(channel.Element("Volume"),"value",1)))));t.Pan=Math.Max(-1,Math.Min(1,2*D(channel.Element("Pan"),"value",0.5)-1));t.Muted=(string)(channel.Element("Mute")??new XElement("Mute")).Attribute("value")=="true";t.Solo=(string)channel.Attribute("solo")=="true";foreach(var device in channel.Descendants().Where(e=>e.Name.LocalName=="Vst3Plugin"||e.Name.LocalName=="ClapPlugin")){string id=(string)device.Attribute("deviceID")??"",format=device.Name.LocalName=="Vst3Plugin"?"VST3":"CLAP";var known=PluginCatalog.Items.Find(delegate(PluginDescriptor d){return d.ClassId==id&&d.Format==format;});var slot=known==null?new PluginSlot{ClassId=id,Name=(string)device.Attribute("deviceName")??id,Format=format,Path="",IsInstrument=(string)device.Attribute("deviceRole")=="instrument"}:known.CreateSlot();slot.Bypassed=(string)(device.Element("Enabled")??new XElement("Enabled")).Attribute("value")=="false";var state=device.Element("State");if(state!=null){byte[] bytes=Bytes(zip.GetEntry((string)state.Attribute("path")),3*1024*1024);if(format=="VST3")bytes=VstPreset.Read(bytes);slot.State=Convert.ToBase64String(bytes);}foreach(var parameter in device.Elements("Parameters").Elements("RealParameter")){string key=(string)parameter.Attribute("id");if(!String.IsNullOrEmpty(key)&&parameter.Attribute("parameterID")!=null)parameterTargets[key]="Plugin:"+slot.Id.ToString()+":"+unchecked((uint)(int)D(parameter,"parameterID",0));}t.Plugins.Add(slot);if(known==null)result.Warnings.Add(t.Name+": unavailable "+format+" "+slot.Name+" retained without substitution.");if(slot.IsInstrument)t.ExternalMidi=false;}}
