  private static void ReadDawClip(XElement clip,Track t,ProjectDocument p,double parent,Func<string,string> extract,List<string> warnings){
   double start=parent+D(clip,"time",0),length=D(clip,"duration",4),play=D(clip,"playStart",0);if(length<=0)return;var notes=clip.Element("Notes");var audio=clip.Descendants("Audio").FirstOrDefault();
   if(notes!=null){var r=ProjectFactory.CreateRegion((string)clip.Attribute("name")??"MIDI",Math.Max(0,start),length);foreach(var n in notes.Elements("Note")){double at=D(n,"time",0)-play,dur=D(n,"duration",0.25);if(at>=0&&at<length)r.Notes.Add(new MidiNote{StartBeat=at,LengthBeats=Math.Min(dur,length-at),Pitch=(int)D(n,"key",60),Velocity=Math.Max(1,Math.Min(127,(int)Math.Round(D(n,"vel",0.8)*127)))});}r.Muted=(string)clip.Attribute("enable")=="false";t.Regions.Add(r);}
   else if(audio!=null){var f=audio.Element("File");if(f==null)return;string name=(string)f.Attribute("path");bool external=(string)f.Attribute("external")=="true";var r=ProjectFactory.CreateRegion((string)clip.Attribute("name")??Path.GetFileNameWithoutExtension(name),Math.Max(0,start),length);r.MediaPath=external?Path.GetFullPath(name):extract(name);r.Muted=(string)clip.Attribute("enable")=="false";r.AudioOffsetSeconds=(string)clip.Attribute("contentTimeUnit")=="seconds"?play:play*60/p.Tempo;t.Regions.Add(r);}
   else foreach(var inner in clip.Elements("Clips").Elements("Clip"))ReadDawClip(inner,t,p,start,extract,warnings);
  }
  private static string LiveValue(XElement e,string name,string fallback){var n=e==null?null:e.Element(name);return n==null?fallback:(string)n.Attribute("Value")??fallback;}
  private static double LiveNumber(XElement e,string name,double fallback){double n;return Double.TryParse(LiveValue(e,name,""),NumberStyles.Float,CultureInfo.InvariantCulture,out n)?n:fallback;}
  public static ImportResult ImportAls(string file){
   var result=new ImportResult{Project=new ProjectDocument{Name=Path.GetFileNameWithoutExtension(file)}};var p=result.Project;XDocument xml;using(var stream=File.OpenRead(file))using(var gz=new GZipStream(stream,CompressionMode.Decompress))xml=ReadXml(gz);
   var live=xml.Descendants("LiveSet").FirstOrDefault();if(live==null)throw new InvalidDataException("No Ableton LiveSet found.");var tempo=live.Descendants("Tempo").FirstOrDefault();p.Tempo=LiveNumber(tempo,"Manual",120);
   foreach(var node in live.Element("Tracks").Elements().Where(e=>e.Name.LocalName=="MidiTrack"||e.Name.LocalName=="AudioTrack")){
    var t=ProjectFactory.CreateTrack(LiveValue(node.Element("Name"),"EffectiveName","Imported track"),node.Name.LocalName=="MidiTrack"?TrackType.Midi:TrackType.Audio);t.ExternalMidi=false;
    foreach(var clip in node.Descendants().Where(e=>e.Name.LocalName==(t.Type==TrackType.Midi?"MidiClip":"AudioClip"))){
     // Session clips with no positive arrangement duration are skipped explicitly.
     double start=LiveNumber(clip,"CurrentStart",-1),end=LiveNumber(clip,"CurrentEnd",-1);if(start<0||end<=start)continue;
     var r=ProjectFactory.CreateRegion(LiveValue(clip,"Name","Imported clip"),start,end-start);var loop=clip.Element("Loop");double offset=LiveNumber(loop,"StartRelative",0)+LiveNumber(loop,"LoopStart",0);
     if(t.Type==TrackType.Midi){foreach(var key in clip.Descendants("KeyTrack")){int pitch=(int)LiveNumber(key,"MidiKey",60);foreach(var n in key.Descendants("MidiNoteEvent")){double at=D(n,"Time",0)-offset,dur=D(n,"Duration",0.25);if(at>=0&&at<r.LengthBeats)r.Notes.Add(new MidiNote{StartBeat=at,LengthBeats=Math.Min(dur,r.LengthBeats-at),Pitch=pitch,Velocity=Math.Max(1,Math.Min(127,(int)D(n,"Velocity",100)))});}}}
     else{string media=clip.Descendants("FileRef").Select(f=>LiveValue(f,"Path","")).FirstOrDefault(s=>s.Length>0);if(String.IsNullOrEmpty(media)){result.Warnings.Add(r.Name+": missing sample reference.");continue;}if(!Path.IsPathRooted(media))media=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(file),media));r.MediaPath=media;r.AudioOffsetSeconds=offset*60/p.Tempo;if(!File.Exists(media))result.Warnings.Add("Missing media: "+media);}
     t.Regions.Add(r);
    }p.Tracks.Add(t);
   }result.Warnings.Add("ALS subset: arrangement MIDI/audio clips. Live devices, mixer levels/routing, warps, clip envelopes, grooves and session launch state are not translated. Sampler audition is enabled; original Live devices are not restored.");ProjectValidator.Validate(p);return result;
  }
