    if(available&&!Path.GetExtension(sample).Equals(".wav",StringComparison.OrdinalIgnoreCase))try{sample=MediaImport.Decode(sample,Path.Combine(Path.GetDirectoryName(SettingsStore.DefaultPath),"Imported Media"));}catch(Exception ex){available=false;if(missingSamples.Add(sample))result.Warnings.Add("Could not decode FL sample (silent region retained): "+Path.GetFileName(sample)+": "+ex.Message);}
    Track t;if(!audioTracks.TryGetValue(clip[0],out t)){string label;channelNames.TryGetValue(clip[0],out label);audioTracks[clip[0]]=t=ProjectFactory.CreateTrack(label??Path.GetFileNameWithoutExtension(sample),TrackType.Audio);p.Tracks.Add(t);}
    string regionName=(available?"":"[Missing] ")+Path.GetFileNameWithoutExtension(sample);regionName=regionName.Substring(0,Math.Min(ProjectValidator.MaxNameLength,regionName.Length));
    var region=ProjectFactory.CreateRegion(regionName,clip[1]/(double)ppq,Math.Max(.25,clip[2]/(double)ppq));region.MediaPath=sample;t.Regions.Add(region);
   }
   result.Warnings.Add("Imported FLP notes use the built-in Sampler for audition. Original FL devices and timbres are NOT restored.");result.Warnings.Add("FLP subset: pattern notes and pattern playlist timing, grouped by rack channel. FL devices/presets, slide notes, automation, mixer routing, audio trims and time stretching are not translated. Missing sample paths are reported. Sampler audition is enabled; choose a compatible VST3 / CLAP instrument to replace it.");ProjectValidator.Validate(p);return result;
  }
  private static int FlPlaylistStride(byte[] data){if(data.Length==0)return 32;int best=0;double score=0;foreach(int stride in new[]{32,60,68,80,88}){if(data.Length%stride!=0)continue;int count=data.Length/stride,valid=0;for(int i=0;i<Math.Min(count,1000);i++)if(BitConverter.ToUInt16(data,i*stride+4)==20480&&BitConverter.ToUInt32(data,i*stride+8)<UInt32.MaxValue/2)valid++;double s=valid/(double)Math.Min(count,1000);if(s>score){best=stride;score=s;}}return score>.9?best:0;}
  private static string FlText(byte[] bytes,bool unicode){string s=(unicode?Encoding.Unicode:Encoding.UTF8).GetString(bytes).TrimEnd('\0');if(String.IsNullOrWhiteSpace(s))return "Imported";s=s.Replace("\0",String.Empty);return s.Substring(0,Math.Min(120,s.Length));}
  private static string Text(byte[] bytes){return (bytes.Length>1&&bytes[1]==0?Encoding.Unicode:Encoding.UTF8).GetString(bytes).TrimEnd('\0');}
  private static int ReadVar(BinaryReader r){int v=0;for(int shift=0;shift<28;shift+=7){int b=r.ReadByte();v|=(b&127)<<shift;if((b&128)==0)return v;}throw new InvalidDataException("FLP variable length invalid.");}
 }
 public static class VstPreset
 {
  public static byte[] Write(string id,byte[] state){if(state.Length<16||Encoding.ASCII.GetString(state,0,6)!="SXVST3")return state;int a=BitConverter.ToInt32(state,8),b=BitConverter.ToInt32(state,12);if(a<0||b<0||16L+a+b!=state.Length)throw new InvalidDataException("Invalid VST3 state.");using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write(Encoding.ASCII.GetBytes("VST3"));w.Write(1);w.Write(Encoding.ASCII.GetBytes(id.PadRight(32,'0').Substring(0,32)));w.Write(48L+a+b);w.Write(state,16,a+b);w.Write(Encoding.ASCII.GetBytes("List"));w.Write(b>0?2:1);w.Write(Encoding.ASCII.GetBytes("Comp"));w.Write(48L);w.Write((long)a);if(b>0){w.Write(Encoding.ASCII.GetBytes("Cont"));w.Write(48L+a);w.Write((long)b);}return m.ToArray();}}
  public static byte[] Read(byte[] bytes){if(bytes.Length<48||Encoding.ASCII.GetString(bytes,0,4)!="VST3")return bytes;using(var m=new MemoryStream(bytes))using(var r=new BinaryReader(m)){m.Position=40;long list=r.ReadInt64();if(list<48||list>bytes.Length-8)throw new InvalidDataException("Invalid VST3 preset list.");m.Position=list;if(Encoding.ASCII.GetString(r.ReadBytes(4))!="List")throw new InvalidDataException("VST3 chunk list missing.");int count=r.ReadInt32();byte[] a=new byte[0],b=new byte[0];if(count<0||count>128)throw new InvalidDataException("Invalid VST3 chunks.");for(int i=0;i<count;i++){string name=Encoding.ASCII.GetString(r.ReadBytes(4));long offset=r.ReadInt64(),size=r.ReadInt64();if(offset<48||size<0||offset+size>list)throw new InvalidDataException("Invalid VST3 chunk.");if(name=="Comp"||name=="Cont"){byte[] data=new byte[(int)size];Array.Copy(bytes,offset,data,0,size);if(name=="Comp")a=data;else b=data;}}using(var output=new MemoryStream())using(var w=new BinaryWriter(output)){w.Write(new byte[]{83,88,86,83,84,51,1,0});w.Write(a.Length);w.Write(b.Length);w.Write(a);w.Write(b);return output.ToArray();}}}
 }
